/**
 * @method
 * @name rmComma
 * @description rm Comma 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.rmComma = function (str) {

    //    if( str == null || str == "" || str == 0 ) return '';
    //    if( str == null || str == ""  ) return '';
    if( str == null || str === ""  ) return Number(str);   // 2009.07.02 수정. 항목 미입력시 합계 오류발생

    reg =  new RegExp(",","g");

    return Number(str.replace(reg,''));
};

/**
 * @method
 * @name edit789
 * @description edit789 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.edit789 = async function () {
    if(!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) return ;

    if(($c.util.getComponent('cal_isuexerDd').getValue() == null ? '' : String($c.util.getComponent('cal_isuexerDd').getValue())) === '' || $c.util.getComponent('cal_isuexerDd').length === 0 ||
        ($c.util.getComponent('ipt_isuexerRnd').getValue() == null ? '' : String($c.util.getComponent('ipt_isuexerRnd').getValue())) === '' || $c.util.getComponent('ipt_isuexerRnd').length === 0 ) {
        await $c.win.alert("수정하시려면, 리스트에서 선택후 수정하세요.");
        return ;
    }

    if($c.util.getComponent("dma_RegisterReq").get("isuexerDdCheck") !== $c.util.getComponent('cal_isuexerDd').getValue()) {
        await $c.win.alert("발행일을 수정하시면 자료를 갱신 할 수 없습니다.");
        return;
    }

    if($c.util.getComponent("dma_RegisterReq").get("isuexerRndCheck") !== $c.util.getComponent('ipt_isuexerRnd').getValue()) {
        await $c.win.alert("회차를 수정하시면 자료를 갱신 할 수 없습니다.");
        return;
    }

    $c.util.getComponent("dma_RegisterReq").set("transKind", 1); // 신규: 0 , 수정 : 1 , 삭제 : 3

    await scwin.register() ;

};

/**
 * @method
 * @name new789
 * @description new789 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.new789 = async function () {
    if(!await (async () => { const c = $c.util.getComponent("trnsmYn"); const v = (c && c.getValue) ? String(c.getValue() ?? "") : ""; if (v === "Y") { await $c.win.alert("이미 제출 되어 신규작성/수정/삭제 할 수 없습니다."); return false; } return true; })()) return ;

    $c.util.getComponent("dma_RegisterReq").set("transKind", 0); // 신규: 0 , 수정 : 1 , 삭제 : 3

    // ??? 조회 목록중에 청구일련번호 같은것이 있는지 체크 필

    await scwin.register() ;

};
